<?php
require dirname(__DIR__).'/_init.php';use App\Core\AccessControl;use App\Core\Database;
AccessControl::require('appointments.manage');$rows=Database::connection()->query("SELECT a.*,p.patient_number,p.full_name,d.name doctor_name FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id ORDER BY appointment_date DESC,appointment_time DESC LIMIT 200")->fetchAll();require dirname(__DIR__).'/_layout_top.php';?>
<div class="d-flex justify-content-between mb-3"><h2>Appointments</h2><a class="btn btn-primary" href="/appointments/create.php">Book appointment</a></div><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Patient</th><th>Doctor</th><th>Date</th><th>Time</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['patient_number'].' - '.$r['full_name'])?></td><td><?=e($r['doctor_name'])?></td><td><?=e($r['appointment_date'])?></td><td><?=e($r['appointment_time'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='booked'):?><form method="post" action="/appointments/cancel.php" data-confirm="Cancel this appointment?"><?=App\Core\CSRF::field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input class="form-control form-control-sm mb-1" name="reason" placeholder="Cancellation reason" required><button class="btn btn-sm btn-outline-danger">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php require dirname(__DIR__).'/_layout_bottom.php';?>
